import random
import math
from fractions import Fraction

def generate_d_regular_graph(n, d):
    if (n * d) % 2 != 0:
        return None
    graph = [[0] * n for _ in range(n)]
    edges = set()
    while len(edges) < d * n // 2:
        u = random.randint(0, n - 1)
        v = random.randint(0, n - 1)
        if u != v and (u, v) not in edges and (v, u) not in edges:
            graph[u][v] = 1
            graph[v][u] = 1
            edges.add((u, v))
    return graph

def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        max_row = i
        for j in range(i + 1, n):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
        if matrix[i][i] == 0:
            return None
        for j in range(i + 1, n):
            factor = Fraction(matrix[j][i], matrix[i][i])
            for k in range(n):
                matrix[j][k] -= factor * matrix[i][k]
    return matrix

def rank_of_matrix(matrix):
    reduced_matrix = gaussian_elimination(matrix)
    if reduced_matrix is None:
        return 0
    n = len(reduced_matrix)
    rank = 0
    for row in reduced_matrix:
        if any(row[j] != 0 for j in range(n)):
            rank += 1
    return rank

def compute_hdw(graph):
    n = len(graph)
    matrix = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(i + 1, n):
            if graph[i][j] == 1:
                matrix[i][j] = -1
                matrix[j][i] = -1
                matrix[i][n] += 1
                matrix[j][n] += 1
    return rank_of_matrix(matrix)

def compute_circuit_width(graph):
    n = len(graph)
    edges = [(i, j) for i in range(n) for j in range(i + 1, n) if graph[i][j] == 1]
    min_width = float('inf')
    for d in range(2, n + 1):
        for s in range(2 ** (d - 1), 2 ** d):
            width = 0
            visited = [False] * n
            stack = []
            for u in range(n):
                if not visited[u]:
                    stack.append(u)
                    while stack:
                        v = stack.pop()
                        visited[v] = True
                        width += 1
                        for w in range(n):
                            if graph[v][w] == 1 and not visited[w]:
                                stack.append(w)
            min_width = min(min_width, width)
    return min_width

